function event(value,id,{eventId,type,now,notes='',occurredAt=now,version=null}){validate(value);if(!iso(now)||!iso(occurredAt))throw Error('Invalid event time');const result=clone(value),r=result.sorties.find(r=>r.id===id);if(!r)throw Error('Flight not found');if(r.events.some(e=>e.id===eventId))return result;if(['landing','abort','outcome-unknown'].includes(type)&&r.phase!=='AIRBORNE')throw Error('This flight is no longer recorded airborne');if(type==='landing'){if(Date.parse(occurredAt)>Date.parse(now)+60000||r.takeoffAt&&Date.parse(occurredAt)<Date.parse(r.takeoffAt))throw Error('Landing must follow take-off and cannot be in the future');r.landingAt=occurredAt;r.phase='LANDED';}if(type==='outcome-unknown'){if(!notes.trim())throw Error('Explain why the landing/outcome is unknown');r.phase='OUTCOME_UNKNOWN';}if(r.events.length&&Date.parse(now)<Date.parse(r.events[r.events.length-1].recordedAt)-60000)r.clockUncertain=true;r.events.push({id:eventId,type,recordedAt:now,occurredAt,notes,source:'pilot-entered',appVersion:version});return validate(result);}
function debrief(value,id,data){const result=clone(validate(value)),r=result.sorties.find(r=>r.id===id);if(!r||r.phase==='AIRBORNE')throw Error('Record landing or an explicitly unknown outcome before debrief');if(r.assessment==='NOT_FLOWN'&&data.outcome&&!['cancelled','postponed','unknown'].includes(data.outcome))throw Error('A cancelled/postponed plan cannot be recorded as a completed flight');if(r.takeoffAt&&['cancelled','postponed'].includes(data.outcome))throw Error('A flight with take-off must be completed, partial, aborted or unknown');if(!iso(data.recordedAt)||typeof data.note!=='string'||typeof data.defect!=='boolean'||typeof data.nothingToReport!=='boolean')throw Error('Invalid debrief');if(data.defect&&data.nothingToReport)throw Error('A defect and Nothing to report cannot both be selected');if(data.defect&&!data.note.trim())throw Error('Describe the defect and follow-up');if(data.landingCharge!==null&&(!Number.isFinite(data.landingCharge)||data.landingCharge<0||data.landingCharge>100))throw Error('Landing charge must be 0–100% or explicitly unknown');const complete=['completed','partial','aborted','cancelled','postponed','unknown'].includes(data.outcome)&&(data.defect||data.nothingToReport)&&(!data.defect||data.followup?.trim());r.debriefs.push(clone({...data,complete}));if(complete&&r.phase!=='OUTCOME_UNKNOWN')r.phase='DEBRIEF_COMPLETE';return validate(result);}
function correct(value,id,{takeoffAt,landingAt,reason,now,eventId,version=null}){const result=clone(validate(value)),r=result.sorties.find(r=>r.id===id);if(!r||!reason?.trim()||!iso(now)||!(takeoffAt===null||iso(takeoffAt))||!(landingAt===null||iso(landingAt)))throw Error('Provide valid corrected times (or explicit unknown) and the reason');if(r.phase==='AIRBORNE')throw Error('Record landing or unknown outcome before correcting times');if(landingAt&&takeoffAt&&Date.parse(landingAt)<Date.parse(takeoffAt)||[takeoffAt,landingAt].some(v=>v&&Date.parse(v)>Date.parse(now)+60000))throw Error('Corrected flight times are inconsistent');r.events.push({id:eventId,type:'time-correction',recordedAt:now,occurredAt:now,notes:reason,previous:{takeoffAt:r.takeoffAt,landingAt:r.landingAt},corrected:{takeoffAt,landingAt},appVersion:version,source:'pilot-entered'});r.takeoffAt=takeoffAt;r.landingAt=landingAt;if(r.assessment!=='NOT_FLOWN'&&(!takeoffAt||!landingAt))r.phase='OUTCOME_UNKNOWN';r.clockUncertain=true;return validate(result);}
function elapsed(record,now=Date.now()){if(!record?.takeoffAt)return null;const end=record.landingAt?Date.parse(record.landingAt):record.phase==='AIRBORNE'?now:null;return end===null?null:Math.max(0,(end-Date.parse(record.takeoffAt))/60000);}
